from typing import Any


class Solver:
    def __init__(self):
        """
        Pre-warm the internal sqrtm function with a small matrix
        to load shared libraries and reduce first-call overhead.
        """
        # Warm up with a small test matrix
        try:
            warm = np.array([[1.0, 2.0], [3.0, 4.0]], dtype=np.float64, order='C')
            _ = recursive_schur_sqrtm(warm)
        except Exception:
            pass

    def solve(self, problem: dict[str, np.ndarray], **kwargs) -> dict[str, dict[str, list[list[complex]]]]:
        """
        Computes the principal matrix square root X such that X @ X = A.

        :param problem: A dictionary with key "matrix" containing a list of lists
                        of complex numbers (strings like "1+2j" or complex objects).
        :return: A dictionary with key "sqrtm" containing a dictionary with key
                 "X": A list of lists representing the principal square root matrix X.
        """
        A_list = problem["matrix"]

        # Convert to numpy complex array efficiently
        try:
            A = np.array(A_list, dtype=complex, order='C')
        except (ValueError, TypeError):
            # Fallback: handle non-standard formats
            try:
                n = len(A_list)
                m = len(A_list[0]) if n > 0 else 0
                A = np.array(A_list, dtype=np.object_)
                # Check if already complex numbers
                if np.issubdtype(A.dtype, np.complexfloating):
                    A = np.asarray(A, dtype=complex, order='C')
                else:
                    # Convert element-wise
                    flat = []
                    for row in A_list:
                        for elem in row:
                            if isinstance(elem, complex):
                                flat.append(elem)
                            elif isinstance(elem, str):
                                # Handle formats like "5+1j", "5+1i" etc.
                                s = elem.replace('i', 'j')
                                flat.append(complex(s))
                            else:
                                flat.append(complex(elem))
                    A = np.array(flat, dtype=complex, order='C').reshape(n, m)
            except Exception:
                logging.error("Failed to convert input matrix to complex array.")
                return {"sqrtm": {"X": []}}

        # Ensure square
        if A.ndim != 2 or A.shape[0] != A.shape[1]:
            logging.error(f"Input matrix is not square: {A.shape}")
            return {"sqrtm": {"X": []}}

        try:
            # Call the compiled internal function directly for speed
            result = recursive_schur_sqrtm(A)
            X = result[0]

            # Check for issues
            if result[3] < 0:  # info < 0 indicates error
                logging.error(f"recursive_schur_sqrtm failed with info={result[3]}")
                return {"sqrtm": {"X": []}}

        except Exception as e:
            logging.error(f"Matrix square root computation failed: {e}")
            return {"sqrtm": {"X": []}}

        # Convert to list of lists (preserves complex Python objects)
        X_list = X.tolist()

        return {"sqrtm": {"X": X_list}}
