import logging
from typing import Any, List

# Try to import the fastest internal function; fall back to public API
_use_internal = True
try:
    from scipy.linalg._matfuncs import recursive_schur_sqrtm
except ImportError:
    _use_internal = False
    import scipy.linalg


class Solver:
    """
    Solver for matrix square root problem.

    Given a square matrix A (potentially complex), compute its principal 
    matrix square root X such that X @ X = A, where X has eigenvalues 
    with non-negative real parts.
    """

    def __init__(self):
        """
        Pre-warm the underlying functions to reduce first-call overhead.
        Compilation and warmup time does not count towards runtime.
        """
        # Warm up with a moderate-sized matrix to load libraries
        try:
            warm = np.array([[1.0, 2.0], [3.0, 4.0]], dtype=np.float64, order='C')
            if _use_internal:
                _ = recursive_schur_sqrtm(warm)
            else:
                _ = scipy.linalg.sqrtm(warm, disp=True)
        except Exception:
            pass

    def solve(self, problem: dict, **kwargs) -> dict:
        """
        Computes the principal matrix square root.

        Args:
            problem: Dictionary with key "matrix" containing a list of lists
                     of numbers or strings representing complex numbers.

        Returns:
            Dictionary with key "sqrtm" containing a dict with key "X"
            mapping to a list of lists of complex numbers.
        """
        A_list = problem.get("matrix")
        if A_list is None:
            logging.error("Problem does not contain 'matrix' key.")
            return {"sqrtm": {"X": []}}

        # Convert input to numpy complex array efficiently
        try:
            # Fast path: direct conversion (works for strings like "1+2j" and complex objects)
            A = np.asarray(A_list, dtype=complex, order='C')
        except (ValueError, TypeError):
            # Slow fallback: handle non-standard formats element-wise
            try:
                A = self._parse_matrix(A_list)
            except Exception:
                logging.error("Failed to convert input matrix to complex array.")
                return {"sqrtm": {"X": []}}

        # Validate square shape
        if A.ndim != 2 or A.shape[0] != A.shape[1]:
            logging.error(f"Input matrix is not square: {A.shape}")
            return {"sqrtm": {"X": []}}

        try:
            if _use_internal:
                result = recursive_schur_sqrtm(A)
                X = result[0]
                # Check for errors (info < 0 means failure)
                if result[3] < 0:
                    logging.error(f"recursive_schur_sqrtm failed with info={result[3]}")
                    return {"sqrtm": {"X": []}}
            else:
                # Fallback to public API with disp=True (no error computation)
                X = scipy.linalg.sqrtm(A, disp=True)
        except Exception as e:
            logging.error(f"Matrix square root computation failed: {e}")
            return {"sqrtm": {"X": []}}

        # Convert to list of lists of Python complex numbers
        X_list = X.tolist()

        return {"sqrtm": {"X": X_list}}

    @staticmethod
    def _parse_matrix(matrix_list: List[List]) -> np.ndarray:
        """
        Parse a list of lists into a complex numpy array, handling 
        various input formats (strings, numbers, complex objects).
        """
        n_rows = len(matrix_list)
        if n_rows == 0:
            return np.empty((0, 0), dtype=complex)
        n_cols = len(matrix_list[0])

        # Flatten and convert
        flat = []
        for row in matrix_list:
            for elem in row:
                if isinstance(elem, (int, float, complex)):
                    flat.append(complex(elem))
                elif isinstance(elem, str):
                    # Handle Python-style complex strings like "1+2j" or "1-2j"
                    # Also handle MATLAB-style "1+2i"
                    s = elem.replace(' ', '').replace('i', 'j')
                    flat.append(complex(s))
                else:
                    flat.append(complex(elem))

        return np.array(flat, dtype=complex, order='C').reshape(n_rows, n_cols)
